1	import { idbDelete, idbGetAllByBusiness, idbPut } from "@/lib/offline-db";
2	import type { DiscountType } from "@/app/business/[businessId]/pos/actions";
3	import type { TicketCartItemInput } from "@/app/business/[businessId]/pos/ticket-actions";
4	
5	export type PendingSaleStatus = "pending" | "syncing" | "error";
6	
7	export type PendingRetailSale = {
8	  clientRef: string;
9	  businessId: string;
10	  kind: "retail";
11	  createdAt: string;
12	  status: PendingSaleStatus;
13	  errorMessage?: string;
14	  payload: {
15	    cashierId: string;
16	    items: { productId: string; qty: number; disc: number; discType: DiscountType }[];
17	    paymentMethod: string;
18	    received: number | null;
19	    orderDisc: number;
20	    orderDiscType: DiscountType;
21	    customerId: string | null;
22	    selfOrderIds: string[];
23	  };
24	};
25	
26	export type PendingTicketSale = {
27	  clientRef: string;
28	  businessId: string;
29	  kind: "ticket";
30	  createdAt: string;
31	  status: PendingSaleStatus;
32	  errorMessage?: string;
33	  payload: {
34	    cashierId: string;
35	    items: TicketCartItemInput[];
36	    paymentMethod: string;
37	    received: number | null;
38	    memberId: string | null;
39	  };
40	};
41	
42	export type PendingSale = PendingRetailSale | PendingTicketSale;
43	
44	export async function enqueueSale(sale: PendingSale): Promise<void> {
45	  await idbPut(sale);
46	}
47	
48	export async function listPending(businessId: string): Promise<PendingSale[]> {
49	  const rows = await idbGetAllByBusiness<PendingSale>(businessId);
50	  return rows.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
51	}
52	
53	export async function markSyncing(sale: PendingSale): Promise<void> {
54	  await idbPut({ ...sale, status: "syncing", errorMessage: undefined });
55	}
56	
57	export async function markSynced(clientRef: string): Promise<void> {
58	  await idbDelete(clientRef);
59	}
60	
61	export async function markError(sale: PendingSale, message: string): Promise<void> {
62	  await idbPut({ ...sale, status: "error", errorMessage: message });
63	}
64	
65	export async function discardPending(clientRef: string): Promise<void> {
66	  await idbDelete(clientRef);
67	}
