69	// Stok server-side belum tahu apa-apa soal penjualan yang masih di antrian
70	// offline — kurangi tampilan stok kasir secara lokal supaya tidak menjual
71	// melebihi yang sebenarnya tersisa, sampai antrian ini tersinkron.
72	export function pendingStockDeltas(pending: PendingSale[]): Record<string, number> {
73	  const deltas: Record<string, number> = {};
74	  for (const sale of pending) {
75	    if (sale.kind !== "retail") continue;
76	    for (const item of sale.payload.items) {
77	      deltas[item.productId] = (deltas[item.productId] ?? 0) + item.qty;
78	    }
79	  }
80	  return deltas;
81	}
