1	// Service worker manual (bukan plugin build-time) — Serwist/next-pwa belum
2	// jelas kompatibel dengan Turbopack yang dipakai proyek ini (lihat catatan
3	// resmi di node_modules/next/dist/docs/01-app/02-guides/progressive-web-apps.md).
4	// Cakupan sengaja dibatasi ketat: hanya halaman POS + aset statis yang dapat
5	// fallback offline. Halaman lain (Neraca, Laporan, dst.) sengaja TIDAK
6	// disentuh sama sekali di sini — menampilkan data keuangan basi seolah live
7	// itu berbahaya, beda kelas risiko dengan kasir yang memang didesain toleran
8	// terhadap data stok/harga yang agak basi.
9	const CACHE_NAME = "kasirku-pos-v1";
10	
11	const STATIC_PREFIXES = ["/_next/static/"];
12	const EXTRA_ALLOWED_PATHS = ["/favicon.ico", "/manifest.webmanifest"];
13	const POS_PATH_RE = /^\/business\/[^/]+\/pos(\/check-in)?\/?$/;
14	
15	function isAllowedPath(pathname) {
16	  if (STATIC_PREFIXES.some((prefix) => pathname.startsWith(prefix))) return true;
17	  if (EXTRA_ALLOWED_PATHS.includes(pathname)) return true;
18	  return POS_PATH_RE.test(pathname);
19	}
20	
21	self.addEventListener("install", () => {
22	  self.skipWaiting();
23	});
24	
25	self.addEventListener("activate", (event) => {
26	  event.waitUntil(
27	    caches
28	      .keys()
29	      .then((names) =>
30	        Promise.all(names.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name))),
31	      )
32	      .then(() => self.clients.claim()),
33	  );
34	});
35	
36	self.addEventListener("fetch", (event) => {
37	  const request = event.request;
38	  if (request.method !== "GET") return;
39	
40	  const url = new URL(request.url);
41	  if (url.origin !== self.location.origin) return;
42	  if (!isAllowedPath(url.pathname)) return;
43	
44	  // Network-first: selama online, SW tidak pernah menyajikan konten basi —
45	  // cache murni jaring pengaman saat fetch benar-benar gagal (offline).
46	  event.respondWith(
47	    fetch(request)
48	      .then((response) => {
49	        const copy = response.clone();
50	        caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
51	        return response;
52	      })
53	      .catch(() => caches.match(request).then((cached) => cached || Response.error())),
54	  );
55	});
