9	export default async function PosPage({
10	  params,
11	}: {
12	  params: Promise<{ businessId: string }>;
13	}) {
14	  const { businessId } = await params;
15	  const supabase = await createClient();
16	
17	  // business (DB) and the cashier session (a cookie read, not a query) don't
18	  // depend on each other — fire both at once instead of waiting in sequence.
19	  const [{ data: business }, session] = await Promise.all([
20	    supabase
21	      .from("businesses")
22	      .select(
23	        "id, name, business_type, tax_enabled, tax_rate, service_enabled, service_rate",
24	      )
25	      .eq("id", businessId)
26	      .single(),
27	    getCashierSession(businessId),
28	  ]);
29	
30	  if (!business) {
31	    notFound();
32	  }
33	
34	  if (!session) {
35	    const { data: cashiers } = await supabase
36	      .from("cashiers")
37	      .select("id, name, role")
38	      .eq("business_id", businessId)
39	      .eq("active", true)
40	      .order("created_at", { ascending: true });
41	
42	    return (
43	      <PinScreen
44	        businessId={businessId}
45	        businessName={business.name}
46	        cashiers={cashiers ?? []}
47	      />
48	    );
49	  }
50	
51	  const { data: activeShift } = await supabase
52	    .from("shifts")
53	    .select("id, opening_cash, opened_at")
54	    .eq("business_id", businessId)
55	    .is("closed_at", null)
56	    .maybeSingle();
57	
58	  if (!activeShift) {
59	    return (
60	      <OpenShiftScreen
61	        businessId={businessId}
62	        businessName={business.name}
63	        cashierId={session.cashierId}
64	        cashierName={session.name}
65	      />
66	    );
67	  }
68	
69	  if (business.business_type === "tiket") {
70	    const todayStr = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });
71	    const dayOfWeek = new Date(`${todayStr}T00:00:00`).getDay();
72	
73	    // None of these 4 queries depend on each other's results — run together.
74	    const [
75	      { data: categoryRows },
76	      { data: customPaymentMethodRowsForTiket },
77	      { data: memberRows },
78	      { data: holidayRow },
79	    ] = await Promise.all([
80	      supabase
81	        .from("ticket_categories")
82	        .select(
83	          "id, name, price_weekday, price_holiday, member_price, group_min_qty, group_price",
84	        )
85	        .eq("business_id", businessId)
86	        .eq("active", true)
87	        .is("deleted_at", null)
88	        .order("name", { ascending: true }),
89	      supabase
90	        .from("custom_payment_methods")
91	        .select("name")
92	        .eq("business_id", businessId)
93	        .order("name", { ascending: true }),
94	      supabase
95	        .from("members")
96	        .select("id, name, phone, member_code, valid_from, valid_until")
97	        .eq("business_id", businessId)
98	        .is("deleted_at", null)
99	        .order("name", { ascending: true }),
100	      supabase
101	        .from("ticket_holidays")
102	        .select("id")
103	        .eq("business_id", businessId)
104	        .eq("holiday_date", todayStr)
105	        .maybeSingle(),
106	    ]);
107	    const isHoliday = dayOfWeek === 0 || dayOfWeek === 6 || !!holidayRow;
108	
109	    return (
110	      <TicketPosScreen
111	        businessId={businessId}
112	        businessName={business.name}
113	        cashierId={session.cashierId}
114	        cashierName={session.name}
115	        shiftId={activeShift.id}
116	        categories={(categoryRows ?? []).map((c) => ({
117	          id: c.id,
118	          name: c.name,
119	          priceWeekday: Number(c.price_weekday),
120	          priceHoliday: Number(c.price_holiday),
121	          memberPrice: Number(c.member_price),
122	          groupMinQty: Number(c.group_min_qty),
123	          groupPrice: c.group_price == null ? null : Number(c.group_price),
124	        }))}
125	        members={(memberRows ?? []).map((m) => ({
126	          id: m.id,
127	          name: m.name,
128	          phone: m.phone,
129	          memberCode: m.member_code,
130	          validFrom: m.valid_from,
131	          validUntil: m.valid_until,
132	        }))}
133	        taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
134	        serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
135	        isHoliday={isHoliday}
136	        customPaymentMethods={(customPaymentMethodRowsForTiket ?? []).map((m) => m.name)}
137	      />
138	    );
139	  }
140	
141	  const isFnb = business.business_type === "fnb";
142	
143	  // Same idea as the ticket branch above — these queries are independent, so
144	  // self_orders (FnB only) rides in the same Promise.all batch instead of a
145	  // separate round trip after it — that used to be a real extra waterfall
146	  // on every POS page load for F&B businesses.
147	  const [
148	    { data: products },
149	    { data: openBillRows },
150	    { data: customers },
151	    { data: customPaymentMethodRows },
152	    { data: selfOrderRows },
153	  ] = await Promise.all([
154	    supabase
155	      .from("products")
156	      .select("id, name, category, price, cost, stock, emoji, barcode, sku, variant_label")
157	      .eq("business_id", businessId)
158	      .is("deleted_at", null)
159	      .order("name", { ascending: true }),
160	    supabase
161	      .from("open_bills")
162	      .select("id, label, items, updated_at")
163	      .eq("business_id", businessId)
164	      .order("updated_at", { ascending: false }),
165	    supabase
166	      .from("customers")
167	      .select("id, name, phone")
168	      .eq("business_id", businessId)
169	      .is("deleted_at", null)
170	      .order("name", { ascending: true }),
171	    supabase
172	      .from("custom_payment_methods")
173	      .select("name")
174	      .eq("business_id", businessId)
175	      .order("name", { ascending: true }),
176	    isFnb
177	      ? supabase
178	          .from("self_orders")
179	          .select(
180	            "id, status, created_at, tables(name), self_order_items(product_id, name, qty, price, note)",
181	          )
182	          .eq("business_id", businessId)
183	          .neq("status", "selesai")
184	          .order("created_at", { ascending: true })
185	      : Promise.resolve({ data: null }),
186	  ]);
187	
188	  const selfOrders = (selfOrderRows ?? []) as unknown as SelfOrderRow[];
189	
190	  return (
191	    <PosScreen
192	      businessId={businessId}
193	      businessName={business.name}
194	      cashierId={session.cashierId}
195	      cashierName={session.name}
196	      shiftId={activeShift.id}
197	      products={products ?? []}
198	      taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
199	      serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
200	      openBills={(openBillRows ?? []) as unknown as OpenBillRow[]}
201	      customers={customers ?? []}
202	      isFnb={isFnb}
203	      customPaymentMethods={(customPaymentMethodRows ?? []).map((m) => m.name)}
204	      selfOrders={selfOrders.map((o) => ({
205	        id: o.id,
206	        status: o.status,
207	        createdAt: o.created_at,
208	        tableName: o.tables?.name ?? "Meja terhapus",
209	        items: o.self_order_items.map((i) => ({
210	          productId: i.product_id,
211	          name: i.name,
212	          qty: i.qty,
213	          price: i.price,
214	          note: i.note,
215	        })),
216	      }))}
217	    />
218	  );
219	}
