1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { setCashierSession, clearCashierSession } from "@/lib/cashier-session";
6	import { logActivity } from "@/lib/activity-log";
7	import { buildKitchenPrintJobs, type KitchenPrintJobPayload } from "@/lib/kitchen-print";
8	import { buildKitchenTicket } from "@/lib/escpos";
9	import { buildReceiptBuffer } from "@/lib/receipt-print";
10	
11	type VerifyCashierPinRow = {
12	  id: string;
13	  business_id: string;
14	  name: string;
15	  role: "kasir" | "manajer";
16	};
17	
18	export async function verifyPin(
19	  businessId: string,
20	  cashierId: string,
21	  pin: string,
22	): Promise<{ success: boolean; error?: string }> {
23	  const supabase = await createClient();
24	  const { data, error } = await supabase
25	    .rpc("verify_cashier_pin", { p_cashier_id: cashierId, p_pin: pin })
26	    .single();
27	
28	  if (error || !data) {
29	    return { success: false, error: "PIN salah, coba lagi" };
30	  }
31	
32	  const cashier = data as VerifyCashierPinRow;
33	
34	  // Defensive check: this action is called with client-supplied arguments,
35	  // so don't trust businessId blindly even though the RPC already scopes
36	  // the cashier lookup to businesses the logged-in owner owns.
37	  if (cashier.business_id !== businessId) {
38	    return { success: false, error: "PIN salah, coba lagi" };
39	  }
40	
41	  await setCashierSession({
42	    cashierId: cashier.id,
43	    businessId: cashier.business_id,
44	    name: cashier.name,
45	    role: cashier.role,
46	  });
47	
48	  return { success: true };
49	}
