55	export type DiscountType = "pct" | "amt";
56	
57	export type CartItemInput = {
58	  productId: string;
59	  qty: number;
60	  disc: number;
61	  discType: DiscountType;
62	};
63	
64	export type CheckoutResult =
65	  | {
66	      success: true;
67	      invoiceNumber: string;
68	      transactionId: string;
69	      printJobs: KitchenPrintJobPayload[];
70	      receiptPrintJobs: KitchenPrintJobPayload[];
71	    }
72	  | { success: false; error: string };
73	
74	type CheckoutRpcRow = { transaction_id: string; invoice_number: string; already_existed: boolean };
75	
76	export async function checkout(
77	  businessId: string,
78	  cashierId: string,
79	  items: CartItemInput[],
80	  paymentMethod: string,
81	  received: number | null,
82	  orderDisc: number,
83	  orderDiscType: DiscountType,
84	  customerId: string | null = null,
85	  selfOrderIds: string[] = [],
86	  // Dibuat sekali di browser per penjualan (crypto.randomUUID()) dan dikirim
87	  // ulang apa adanya kalau ini retry dari antrian offline — RPC memakainya
