7	const DB_NAME = "kasirku-offline";
8	const DB_VERSION = 1;
9	const STORE_NAME = "pending_sales";
10	
11	function openDb(): Promise<IDBDatabase> {
12	  return new Promise((resolve, reject) => {
13	    const request = indexedDB.open(DB_NAME, DB_VERSION);
14	
15	    request.onupgradeneeded = () => {
16	      const db = request.result;
17	      if (!db.objectStoreNames.contains(STORE_NAME)) {
18	        const store = db.createObjectStore(STORE_NAME, { keyPath: "clientRef" });
19	        store.createIndex("by-business", "businessId", { unique: false });
20	      }
21	    };
22	
23	    request.onsuccess = () => resolve(request.result);
24	    request.onerror = () => reject(request.error);
25	  });
26	}
27	
28	export async function idbPut<T>(record: T): Promise<void> {
29	  const db = await openDb();
30	  return new Promise((resolve, reject) => {
31	    const tx = db.transaction(STORE_NAME, "readwrite");
32	    tx.objectStore(STORE_NAME).put(record);
33	    tx.oncomplete = () => resolve();
34	    tx.onerror = () => reject(tx.error);
35	  });
36	}
