38	export async function idbGetAllByBusiness<T>(businessId: string): Promise<T[]> {
39	  const db = await openDb();
40	  return new Promise((resolve, reject) => {
41	    const tx = db.transaction(STORE_NAME, "readonly");
42	    const index = tx.objectStore(STORE_NAME).index("by-business");
43	    const request = index.getAll(IDBKeyRange.only(businessId));
44	    request.onsuccess = () => resolve(request.result as T[]);
45	    request.onerror = () => reject(request.error);
46	  });
47	}
